using System.IO;
using Newtonsoft.Json;

#pragma warning disable CS0649 // fields are filled by Newtonsoft.Json

namespace ExtraBuildings
{
    /// <summary>Blueprint in JSON format, generated by tools\gen_*.py.</summary>
    internal sealed class Blueprint
    {
        public string siteId;
        public string displayName;
        public string templateSite = "house";
        public string[] sections;
        /// <summary>Blueprint board relative to the footprint center: x, z, rotation in degrees.</summary>
        public float[] blueprintStand;
        public PileSpec pile;
        /// <summary>Walkable colliders of the plinth (local).</summary>
        public BoxSpec[] colliders;
        /// <summary>Plinth bricks: visuals only, no slots.</summary>
        public DecorSpec[] decor;
        public BrickSpec[] bricks;

        public static Blueprint Load(string path)
        {
            Blueprint bp = JsonConvert.DeserializeObject<Blueprint>(File.ReadAllText(path));
            if (bp == null || string.IsNullOrWhiteSpace(bp.siteId) || bp.sections == null || bp.sections.Length == 0
                || bp.bricks == null || bp.bricks.Length == 0 || bp.pile == null)
            {
                throw new InvalidDataException("Incomplete blueprint: " + path);
            }
            for (int i = 0; i < bp.bricks.Length; i++)
            {
                BrickSpec b = bp.bricks[i];
                if (b.p == null || b.p.Length != 3 || b.s < 0 || b.s >= bp.sections.Length || (b.mode != 0 && b.mode != 1))
                {
                    throw new InvalidDataException($"Blueprint brick {i} is invalid.");
                }
                foreach (int r in b.req ?? new int[0])
                {
                    if (r < 0 || r >= bp.bricks.Length || r == i)
                    {
                        throw new InvalidDataException($"Blueprint brick {i} has an invalid prerequisite {r}.");
                    }
                }
            }
            return bp;
        }
    }

    internal sealed class PileSpec
    {
        public float x;
        public float z;
        public float gap = 0.06f;
        public int perRow = 10;
        public int stack = 2;
    }

    internal sealed class BoxSpec
    {
        public float[] c;
        public float[] s;
    }

    internal sealed class DecorSpec
    {
        public string def;
        public float[] p;
        public float yaw;
    }

    internal sealed class BrickSpec
    {
        /// <summary>Asset name of the brick definition, e.g. Bakery_Brick_2D1CAFD3.</summary>
        public string def;
        /// <summary>Brick center in meters, relative to the footprint center at ground level.</summary>
        public float[] p;
        public float yaw;
        /// <summary>Section index.</summary>
        public int s;
        /// <summary>0 = all prerequisites (All), 1 = any one is enough (Any).</summary>
        public int mode;
        public int[] req;
    }
}
